// Extraido literalmente de SirEdwards_Quiz_v1_1.html (Fase 2 - sin modificar contenido)
// Cargado como script clasico (no ES Module) para no alterar el scope global.

const QUESTIONS = [
  {"n": 21, "q": "¿Cuáles eran las tres embarcaciones de la expedición de Colón en su primer viaje a América?", "a": "La Santa María, la Pinta y la Niña", "cat": "historia", "dif": "medio", "sabias": "La Santa María era la nave capitana y la mayor de las tres embarcaciones, mientras que la Niña y la Pinta eran las otras dos naves de la expedición."},
  {"n": 22, "q": "¿Qué invento desarrollado por Johannes Gutenberg hacia mediados del siglo XV revolucionó la difusión de libros y del conocimiento en Europa?", "a": "La imprenta de tipos móviles", "cat": "historia", "dif": "medio", "sabias": "La imprenta de tipos móviles permitió multiplicar las copias de los libros y aceleró enormemente la difusión de ideas y conocimientos en Europa.", "lz": "A"},
  {"n": 23, "q": "¿Qué famosa batalla de 1815 marcó la derrota final de Napoleón Bonaparte?", "a": "Waterloo", "cat": "historia", "dif": "medio", "sabias": "Tras Waterloo, Napoleón fue enviado al exilio en la remota isla de Santa Elena, donde murió en 1821.", "alias": ["Batalla de Waterloo"], "lz": "A"},
  {"n": 24, "q": "¿Qué pueblo de la antigua Mesopotamia desarrolló uno de los primeros sistemas de escritura, la escritura cuneiforme?", "a": "Los sumerios", "cat": "historia", "dif": "medio", "sabias": "La escritura cuneiforme comenzó utilizándose en Mesopotamia para registrar información administrativa, económica y comercial antes de emplearse también para textos literarios y religiosos.", "alias": ["Sumeria", "Civilización sumeria"], "lz": "A"},
  {"n": 25, "q": "¿Qué documento inglés de 1215 es un antecedente fundamental de la limitación del poder del monarca?", "a": "La Carta Magna", "cat": "historia", "dif": "medio", "sabias": "La Carta Magna de 1215 no creó una democracia moderna, pero estableció principios que contribuyeron posteriormente a limitar el poder arbitrario del gobernante.", "lz": "A"},
  {"n": 26, "q": "¿Qué emperador fue depuesto en 476 d. C., hecho que se toma como final del Imperio romano de Occidente?", "a": "Rómulo Augústulo", "cat": "historia", "dif": "medio", "sabias": "Lo depuso Odoacro, que envió las insignias imperiales a Constantinopla.", "alias": ["Augústulo"]},
  {"n": 27, "q": "¿Quién fue el líder militar cartaginés que cruzó los Alpes con elefantes?", "a": "Aníbal Barca", "cat": "historia", "dif": "medio", "sabias": "Aníbal cruzó los Alpes durante la Segunda Guerra Púnica en una de las campañas militares más célebres de la Antigüedad, aunque las fuentes antiguas difieren sobre el número de elefantes que sobrevivieron.", "lz": "A"},
  {"n": 28, "q": "¿Qué tratado firmado en 1919 estableció las condiciones de paz con Alemania tras la Primera Guerra Mundial?", "a": "El Tratado de Versalles", "cat": "historia", "dif": "medio", "sabias": "El Tratado de Versalles impuso a Alemania importantes pérdidas territoriales, limitaciones militares y reparaciones tras la Primera Guerra Mundial.", "lz": "A"},
  {"n": 29, "q": "¿Quién fue el conquistador español que lideró la conquista del Imperio inca?", "a": "Francisco Pizarro", "cat": "historia", "dif": "medio", "sabias": "Francisco Pizarro capturó al emperador inca Atahualpa en Cajamarca en 1532, un episodio decisivo para la conquista española del Imperio inca.", "lz": "A"},
  {"n": 30, "q": "¿Qué monarcas, conocidos como los Reyes Católicos, gobernaron conjuntamente Castilla y Aragón?", "a": "Isabel I de Castilla y Fernando II de Aragón", "cat": "historia", "dif": "medio", "sabias": "Isabel y Fernando gobernaron conjuntamente Castilla y Aragón, pero ambos reinos conservaron durante su reinado buena parte de sus propias leyes e instituciones."},
  {"n": 31, "q": "¿Qué dos hermanos fueron, según la tradición romana, los fundadores de Roma?", "a": "Rómulo y Remo", "cat": "historia", "dif": "medio", "sabias": "La historia de Rómulo y Remo es una leyenda fundacional romana y cuenta que los hermanos fueron amamantados por una loba antes de la fundación de Roma.", "lz": "B"},
  {"n": 32, "q": "¿Qué conflicto europeo, originado por disputas religiosas y políticas entre católicos y protestantes, terminó en 1648 con los tratados de paz que dieron nombre a la llamada Paz de Westfalia?", "a": "La guerra de los Treinta Años", "cat": "historia", "dif": "medio", "sabias": "La Paz de Westfalia de 1648 puso fin a la Guerra de los Treinta Años, que devastó sobre todo los territorios alemanes del Sacro Imperio.", "lz": "B", "par": [48]},
  {"n": 33, "q": "¿Qué hecho de 1066 inició la conquista normanda de Inglaterra?", "a": "La batalla de Hastings", "cat": "historia", "dif": "medio", "sabias": "Guillermo el Conquistador venció en Hastings en 1066 y se convirtió en rey de Inglaterra, iniciando la conquista normanda del país.", "lz": "A"},
  {"n": 34, "q": "¿Qué gran construcción de Pekín fue el palacio imperial de los emperadores chinos durante casi cinco siglos?", "a": "La Ciudad Prohibida", "cat": "historia", "dif": "medio", "sabias": "La Ciudad Prohibida fue construida durante la dinastía Ming y fue residencia de los emperadores chinos y centro ceremonial y político del imperio durante casi 500 años.", "lz": "A"},
  {"n": 35, "q": "¿Qué conflicto iniciado en 1775 terminó con la independencia de las Trece Colonias británicas de Norteamérica?", "a": "La Guerra de Independencia de EE. UU.", "cat": "historia", "dif": "medio", "sabias": "Aunque la Declaración de Independencia se aprobó en 1776, la guerra entre las Trece Colonias y Gran Bretaña continuó hasta 1783.", "alias": ["Guerra de Independencia de Estados Unidos", "Revolución americana"], "lz": "B"},
  {"n": 36, "q": "¿Qué acontecimiento financiero de octubre de 1929 marcó el inicio de la Gran Depresión?", "a": "El crac de la Bolsa de Nueva York", "cat": "historia", "dif": "medio", "sabias": "El crac bursátil de 1929 fue un factor importante en el inicio de la Gran Depresión, pero la crisis tuvo además otras causas económicas y financieras.", "alias": ["Crac del 29", "Crack del 29"], "lz": "B"},
  {"n": 37, "q": "¿Cómo se denomina el proceso político español iniciado tras la muerte de Franco que condujo a la democracia?", "a": "La Transición española", "cat": "historia", "dif": "medio", "sabias": "La Transición española culminó con la Constitución de 1978 y transformó el sistema político del país tras la dictadura franquista.", "lz": "B"},
  {"n": 38, "q": "¿Qué influyente pensador y economista escocés publicó en 1776 La riqueza de las naciones, obra fundamental que sentó las bases teóricas del liberalismo económico moderno?", "a": "Adam Smith", "cat": "historia", "dif": "medio", "sabias": "La riqueza de las naciones, publicada en 1776, convirtió a Adam Smith en una de las figuras fundamentales de la historia del pensamiento económico moderno.", "lz": "A"},
  {"n": 39, "q": "¿Qué conflicto enfrentó a Atenas y Esparta durante gran parte del siglo V a. C.?", "a": "La Guerra del Peloponeso", "cat": "historia", "dif": "medio", "sabias": "La Guerra del Peloponeso terminó con la derrota de Atenas frente a Esparta y debilitó profundamente al mundo griego antes del ascenso de Macedonia.", "lz": "A"},
  {"n": 40, "q": "¿Cómo se denominó el territorio de la península ibérica bajo dominio musulmán durante gran parte de la Edad Media?", "a": "Al-Ándalus", "cat": "historia", "dif": "medio", "sabias": "Al-Ándalus no fue siempre un único Estado: a lo largo de los siglos estuvo dividido en diferentes entidades políticas, entre ellas los reinos de taifas.", "lz": "A"},
  {"n": 41, "q": "¿Qué pueblo procedente de Escandinavia estableció asentamientos en Inglaterra, Francia y otras zonas de Europa entre los siglos VIII y XI?", "a": "Vikingos", "cat": "historia", "dif": "medio", "sabias": "Los vikingos llegaron a América del Norte siglos antes de los viajes de Colón, y el asentamiento de L'Anse aux Meadows en Terranova constituye una prueba arqueológica de ello.", "lz": "A"},
  {"n": 42, "q": "¿Qué célebre matemático, astrónomo y físico griego de la antigüedad inventó ingeniosos artefactos bélicos de defensa durante el sitio romano de Siracusa en el siglo III a. C.?", "a": "Arquímedes", "cat": "historia", "dif": "medio", "sabias": "Arquímedes destacó tanto en matemáticas como en física y desarrolló principios relacionados con la palanca, la flotación y el movimiento de los cuerpos.", "alias": ["Arquímedes de Siracusa"], "lz": "A"},
  {"n": 43, "q": "¿Qué batalla naval de 1805 confirmó el dominio británico de los mares durante las guerras napoleónicas?", "a": "La batalla de Trafalgar", "cat": "historia", "dif": "medio", "sabias": "En Trafalgar murió el almirante británico Horatio Nelson, que se convirtió posteriormente en uno de los grandes héroes navales de la historia británica.", "lz": "A"},
  {"n": 44, "q": "¿Qué acontecimiento de 1453 marcó tradicionalmente el final de la Edad Media?", "a": "La caída de Constantinopla", "cat": "historia", "dif": "medio", "sabias": "La caída de Constantinopla en 1453 puso fin al Imperio bizantino y convirtió a los otomanos en una de las grandes potencias del Mediterráneo oriental.", "lz": "B", "par": [337]},
  {"n": 45, "q": "¿Qué importante conflicto bélico europeo de principios del siglo XVIII, desencadenado por la muerte sin descendencia de Carlos II de España, alteró profundamente el equilibrio de poder continental?", "a": "La Guerra de Sucesión Española", "cat": "historia", "dif": "medio", "sabias": "La Guerra de Sucesión Española terminó en 1713-1714 con tratados que modificaron profundamente el equilibrio de poder europeo y concedieron territorios a varias potencias.", "lz": "B", "par": [51]},
  {"n": 46, "q": "¿Qué conflicto enfrentó a los estados del norte y del sur de Estados Unidos entre 1861 y 1865?", "a": "La Guerra de Secesión", "cat": "historia", "dif": "medio", "sabias": "La Guerra de Secesión terminó con la victoria de la Unión y fue seguida por la abolición constitucional de la esclavitud mediante la Decimotercera Enmienda.", "lz": "A"},
  {"n": 47, "q": "¿Cómo se denominaba la red de rutas comerciales que conectaba China con Asia Central, Oriente Próximo y Europa?", "a": "La Ruta de la Seda", "cat": "historia", "dif": "medio", "sabias": "La Ruta de la Seda no era una única carretera, sino una extensa red de rutas terrestres y marítimas por las que circulaban mercancías, personas e ideas.", "lz": "A"},
  {"n": 48, "q": "¿Qué conjunto de tratados de 1648 puso fin a la Guerra de los Treinta Años?", "a": "La Paz de Westfalia", "cat": "historia", "dif": "dificil", "sabias": "Los acuerdos se negociaron durante varios años en las ciudades de Münster y Osnabrück.", "lz": "B", "par": [32]},
  {"n": 49, "q": "¿Qué conferencia de 1884-1885 estableció normas para regular la expansión colonial europea y el reconocimiento de reclamaciones territoriales en África?", "a": "La Conferencia de Berlín", "cat": "historia", "dif": "dificil", "sabias": "La conferencia se celebró sin la participación de ningún representante africano, a pesar de que sus decisiones afectaron directamente al futuro de todo el continente.", "lz": "B"},
  {"n": 50, "q": "¿Qué doctrina política y económica desarrollada por Karl Marx y Friedrich Engels defendía la lucha de clases y tuvo una enorme influencia en la política mundial de los siglos XIX y XX?", "a": "El marxismo", "cat": "historia", "dif": "dificil", "sabias": "El Manifiesto Comunista, publicado en 1848, fue escrito por Marx y Engels por encargo de la Liga de los Comunistas y originalmente se publicó en alemán."},
  {"n": 51, "q": "¿Qué tratado de 1713 puso fin a gran parte de la Guerra de Sucesión Española y reconoció a Felipe V como rey de España?", "a": "El Tratado de Utrecht", "cat": "historia", "dif": "dificil", "sabias": "Gran Bretaña obtuvo Gibraltar y Menorca, entre otras concesiones, tras la guerra.", "lz": "A", "par": [45]},
  {"n": 52, "q": "¿Qué tratado de 1494 estableció una línea de demarcación entre las zonas de expansión de Castilla y Portugal?", "a": "El Tratado de Tordesillas", "cat": "historia", "dif": "dificil", "sabias": "El acuerdo fue firmado por Castilla y Portugal en 1494, antes del descubrimiento europeo de Brasil.", "lz": "A"},
  {"n": 53, "q": "¿Qué plan estadounidense anunciado en 1947 proporcionó ayuda económica para la reconstrucción de Europa después de la Segunda Guerra Mundial?", "a": "El Plan Marshall", "cat": "historia", "dif": "dificil", "sabias": "El programa se desarrolló entre 1948 y 1952 y benefició a 16 países europeos.", "lz": "A"},
  {"n": 54, "q": "¿Qué acontecimiento de 1917 llevó a los bolcheviques, liderados por Lenin, a tomar el poder en Rusia?", "a": "La Revolución de Octubre", "cat": "historia", "dif": "dificil", "sabias": "Los bolcheviques tomaron el Palacio de Invierno en Petrogrado, sede del Gobierno Provisional, durante la Revolución de Octubre, consolidando así su toma del poder."},
  {"n": 55, "q": "¿Qué emperador bizantino ordenó la recopilación del Corpus Iuris Civilis, una de las grandes bases del derecho europeo posterior?", "a": "Justiniano I", "cat": "historia", "dif": "dificil", "sabias": "La recopilación fue realizada durante el reinado de Justiniano I en el siglo VI.", "lz": "A"},
  {"n": 87, "q": "¿Qué mar separa la península arábiga de África?", "a": "El mar Rojo", "cat": "geografia", "dif": "medio", "lz": "B", "par": [383]},
  {"n": 88, "q": "¿Qué cordillera rusa marca tradicionalmente el límite oriental de Europa?", "a": "Los montes Urales", "cat": "geografia", "dif": "medio"},
  {"n": 89, "q": "¿Cuál es la isla más grande del mundo que no se considera un continente?", "a": "Groenlandia", "cat": "geografia", "dif": "medio", "sabias": "Es la mayor isla del mundo, con más de 2 millones de km², y alrededor del 80 % de su superficie está cubierta de hielo.", "lz": "A"},
  {"n": 92, "q": "¿Qué lago se encuentra entre Perú y Bolivia y es considerado el lago navegable más alto del mundo?", "a": "El lago Titicaca", "cat": "geografia", "dif": "medio", "sabias": "La cultura uru y los pueblos aimara viven desde hace siglos en sus orillas e islas de totora.", "lz": "A"},
  {"n": 93, "q": "¿Cuál es la montaña más alta de África, con una cumbre situada a unos 5.895 metros sobre el nivel del mar?", "a": "El Kilimanjaro", "cat": "geografia", "dif": "medio", "sabias": "Es un volcán dormido y la montaña aislada más alta del mundo: se alza sola sobre la llanura.", "alias": ["Monte Kilimanjaro"], "lz": "A"},
  {"n": 94, "q": "¿Qué desierto se extiende por gran parte del norte de Chile?", "a": "El desierto de Atacama", "cat": "geografia", "dif": "medio", "lz": "A"},
  {"n": 95, "q": "¿Qué país alberga la región de Transilvania?", "a": "Rumanía", "cat": "geografia", "dif": "medio", "sabias": "La novela «Drácula» (1897), de Bram Stoker, ambientó allí a su conde y la hizo famosa en todo el mundo.", "lz": "A"},
  {"n": 96, "q": "¿Cómo se llama la depresión oceánica más profunda conocida, situada en el océano Pacífico?", "a": "La fosa de las Marianas", "cat": "geografia", "dif": "medio", "sabias": "Su punto más profundo supera los 10.900 m: si se colocara allí el Everest (8.849 m), su cima quedaría a más de 2 km bajo el agua.", "lz": "A"},
  {"n": 97, "q": "¿Qué lago contiene aproximadamente una quinta parte del agua dulce superficial no congelada del planeta y se encuentra en Rusia?", "a": "El lago Baikal", "cat": "geografia", "dif": "medio", "sabias": "Con más de 1.600 m es el lago más profundo del mundo y también uno de los más antiguos, con unos 25–30 millones de años.", "lz": "A"},
  {"n": 98, "q": "¿Qué río forma gran parte de la frontera entre México y Estados Unidos?", "a": "El río Bravo o río Grande", "cat": "geografia", "dif": "medio", "alias": ["Río Bravo del Norte"], "lz": "A"},
  {"n": 99, "q": "¿Qué explorador portugués fue el primero en doblar el cabo de Buena Esperanza y demostrar que era posible navegar hacia el océano Índico desde el Atlántico?", "a": "Bartolomé Díaz", "cat": "geografia", "dif": "medio", "sabias": "En 1488 lo llamó «cabo de las Tormentas»; el rey Juan II de Portugal lo rebautizó «Buena Esperanza» porque abría la ruta hacia la India.", "lz": "A"},
  {"n": 100, "q": "¿En qué mar de Oriente Medio está el punto de tierra más bajo del planeta, a más de 400 m bajo el nivel del mar?", "a": "El mar Muerto", "cat": "geografia", "dif": "medio", "sabias": "Su superficie está a más de 400 m bajo el nivel del mar, el punto de tierra firme más bajo del planeta, y sigue descendiendo alrededor de 1 m al año. Su salinidad es tan alta que es casi imposible hundirse.", "lz": "B"},
  {"n": 101, "q": "¿Qué país está dividido entre Europa y Asia por el estrecho del Bósforo?", "a": "Turquía", "cat": "geografia", "dif": "medio", "lz": "B"},
  {"n": 102, "q": "¿Qué mar interior, el mayor cuerpo de agua cerrado del mundo, se encuentra ubicado entre Europa oriental y Asia occidental?", "a": "El mar Caspio", "cat": "geografia", "dif": "medio", "lz": "A"},
  {"n": 103, "q": "¿Qué canal marítimo artificial separa América del Norte de América del Sur, conectando los océanos Atlántico y Pacífico?", "a": "El canal de Panamá", "cat": "geografia", "dif": "medio", "sabias": "Se abrió en 1914 y ahorró a los barcos el largo rodeo por el cabo de Hornos, en el extremo sur de América.", "lz": "B"},
  {"n": 104, "q": "¿Qué país mide su progreso con el índice de «Felicidad Nacional Bruta»?", "a": "Bután", "cat": "geografia", "dif": "dificil", "sabias": "Bután es uno de los países más montañosos del mundo y limita al norte con China y al sur con India."},
  {"n": 105, "q": "¿Qué estrecho separa Asia de América del Norte?", "a": "El estrecho de Bering", "cat": "geografia", "dif": "dificil", "sabias": "Durante la última glaciación, el nivel del mar descendió lo suficiente como para que Asia y América del Norte quedaran conectadas por una extensa zona de tierra llamada Beringia.", "lz": "A"},
  {"n": 106, "q": "¿Cuál es el único país del mundo cuya bandera nacional no tiene forma rectangular ni cuadrada?", "a": "Nepal", "cat": "geografia", "dif": "dificil", "sabias": "Sus dos triángulos representan, según una interpretación tradicional, las montañas del Himalaya.", "lz": "A"},
  {"n": 141, "q": "¿Qué factor astronómico es la causa principal de las estaciones del año?", "a": "La inclinación del eje terrestre", "cat": "ciencia", "dif": "medio", "sabias": "La inclinación del eje terrestre es de unos 23,4 grados y hace que cada hemisferio reciba distinta cantidad de luz solar a lo largo del año.", "lz": "B"},
  {"n": 142, "q": "¿Cuál es aproximadamente la velocidad de la luz en el vacío?", "a": "300.000 km/s", "cat": "ciencia", "dif": "medio", "sabias": "La luz del Sol tarda aproximadamente 8 minutos y 20 segundos en recorrer la distancia media hasta la Tierra.", "alias": ["300000"], "lz": "B"},
  {"n": 143, "q": "¿Cómo se llama el cambio directo de estado de sólido a gas?", "a": "Sublimación", "cat": "ciencia", "dif": "medio", "sabias": "El hielo seco es un ejemplo cotidiano de sublimación porque pasa directamente de sólido a gas a presión atmosférica, sin convertirse en líquido.", "lz": "A"},
  {"n": 144, "q": "¿En qué orgánulos de las células vegetales tiene lugar principalmente la fotosíntesis?", "a": "Los cloroplastos", "cat": "ciencia", "dif": "medio", "sabias": "Los cloroplastos contienen clorofila, el pigmento que absorbe parte de la energía luminosa utilizada durante la fotosíntesis.", "lz": "A"},
  {"n": 145, "q": "¿Qué parte del cerebro participa especialmente en el equilibrio y la coordinación motora?", "a": "El cerebelo", "cat": "ciencia", "dif": "medio", "lz": "A"},
  {"n": 146, "q": "¿Qué glándula produce hormonas que regulan gran parte del metabolismo del organismo?", "a": "La glándula tiroides", "cat": "ciencia", "dif": "medio", "sabias": "Pesa unos 20 g y necesita yodo para fabricar sus hormonas.", "lz": "A"},
  {"n": 147, "q": "¿Qué unidad del Sistema Internacional se utiliza para medir la frecuencia?", "a": "El hercio", "cat": "ciencia", "dif": "medio", "sabias": "El hercio recibe su nombre del físico alemán Heinrich Hertz, pionero en el estudio experimental de las ondas electromagnéticas.", "alias": ["Hz", "Hertz"], "lz": "B"},
  {"n": 148, "q": "¿Qué grupo sanguíneo es el donante universal de glóbulos rojos?", "a": "O negativo", "cat": "ciencia", "dif": "medio", "lz": "B"},
  {"n": 149, "q": "¿Qué tipo de energía está asociada al movimiento de un cuerpo?", "a": "Energía cinética", "cat": "ciencia", "dif": "medio", "sabias": "La energía cinética aumenta con el cuadrado de la velocidad, por lo que duplicar la velocidad de un objeto cuadruplica su energía cinética si su masa permanece igual.", "lz": "A"},
  {"n": 150, "q": "¿Qué tipo de enlace químico se forma habitualmente cuando un átomo transfiere electrones a otro?", "a": "Enlace iónico", "cat": "ciencia", "dif": "medio", "lz": "A"},
  {"n": 151, "q": "¿Qué orgánulo celular actúa como la central energética de la célula?", "a": "La mitocondria", "cat": "ciencia", "dif": "medio", "sabias": "Las mitocondrias poseen su propio ADN, una de las evidencias que apoyan la idea de que evolucionaron a partir de antiguas bacterias.", "lz": "A"},
  {"n": 152, "q": "¿Qué unidad se utiliza para medir la intensidad de una corriente eléctrica?", "a": "El amperio", "cat": "ciencia", "dif": "medio", "alias": ["Ampere"], "lz": "B"},
  {"n": 153, "q": "¿Qué fenómeno óptico hace que un objeto parezca desplazado cuando se observa a través del agua?", "a": "La refracción", "cat": "ciencia", "dif": "medio", "sabias": "La refracción también explica por qué una pajita introducida en un vaso de agua parece doblarse cuando la observamos desde fuera.", "alias": ["Refracción de la luz"], "lz": "A"},
  {"n": 154, "q": "¿Cómo se denomina la violenta explosión estelar que experimentan algunas estrellas masivas al final de su ciclo de vida?", "a": "Una supernova", "cat": "ciencia", "dif": "medio", "sabias": "Una supernova puede liberar durante un breve periodo una enorme cantidad de energía y producir elementos más pesados que el hierro.", "alias": ["Explosión de supernova"], "lz": "A"},
  {"n": 155, "q": "¿Qué fenómeno físico explica principalmente por qué el cielo diurno se ve azul?", "a": "La dispersión de Rayleigh", "cat": "ciencia", "dif": "dificil", "sabias": "Al amanecer y al atardecer la luz atraviesa más atmósfera y predominan tonos rojizos y anaranjados.", "lz": "A"},
  {"n": 156, "q": "¿Qué astrónomo formuló las leyes que describen el movimiento de los planetas alrededor del Sol?", "a": "Johannes Kepler", "cat": "ciencia", "dif": "dificil", "sabias": "Sus leyes ayudaron a demostrar que las órbitas planetarias son elípticas, no circulares.", "lz": "A"},
  {"n": 157, "q": "¿Qué estructura del oído interno contiene las células sensoriales que transforman las vibraciones sonoras en señales nerviosas?", "a": "La cóclea", "cat": "ciencia", "dif": "dificil", "sabias": "La cóclea humana mide aproximadamente 3,5 cm si se desenrolla.", "lz": "A"},
  {"n": 158, "q": "¿Qué científico formuló el principio de incertidumbre?", "a": "Werner Heisenberg", "cat": "ciencia", "dif": "dificil", "sabias": "No se debe a una limitación de los instrumentos, sino a una propiedad fundamental de la mecánica cuántica.", "lz": "A"},
  {"n": 159, "q": "¿Qué partícula elemental actúa como mediadora de la interacción electromagnética?", "a": "El fotón", "cat": "ciencia", "dif": "dificil", "sabias": "El fotón no tiene masa ni carga eléctrica.", "lz": "A"},
  {"n": 160, "q": "¿Qué isótopo radiactivo del carbono se utiliza habitualmente para datar restos orgánicos relativamente recientes?", "a": "Carbono-14", "cat": "ciencia", "dif": "dificil", "sabias": "El método es especialmente útil para restos de hasta unos 50.000 años.", "alias": ["C-14","C14"], "lz": "B"},
  {"n": 161, "q": "¿Qué ley de la termodinámica establece que la entropía de un sistema aislado no disminuye?", "a": "La segunda ley", "cat": "ciencia", "dif": "dificil", "sabias": "Esta ley ayuda a explicar por qué el calor fluye espontáneamente de los cuerpos calientes a los fríos."},
  {"n": 162, "q": "¿Cómo se denomina el método que permite determinar la edad de materiales mediante la comparación de isótopos radiactivos y sus productos de desintegración?", "a": "La datación radiométrica", "cat": "ciencia", "dif": "dificil", "sabias": "El método se usa para fechar rocas, minerales y restos de materiales muy antiguos."},
  {"n": 163, "q": "¿Qué proceso permite a una célula eliminar componentes dañados mediante un mecanismo controlado de autodigestión?", "a": "Autofagia", "cat": "ciencia", "dif": "dificil", "sabias": "El Nobel de Medicina de 2016 reconoció investigaciones sobre los mecanismos de la autofagia.", "lz": "A"},
  {"n": 164, "q": "¿Qué científico propuso que los elementos químicos podían organizarse periódicamente según sus propiedades y dejó huecos para elementos aún desconocidos?", "a": "Dmitri Mendeléyev", "cat": "ciencia", "dif": "dificil", "sabias": "Algunas de sus predicciones coincidieron después con elementos como el galio y el germanio.", "lz": "A"},
  {"n": 165, "q": "¿Qué planeta tarda más en dar una vuelta sobre sí mismo?", "a": "Venus", "cat": "ciencia", "dif": "dificil", "sabias": "Venus gira en sentido contrario al de la mayoría de los planetas del sistema solar.", "lz": "A"},
  {"n": 192, "q": "¿Qué estilo arquitectónico medieval se caracteriza, entre otros elementos, por los arcos apuntados, las bóvedas de crucería y los grandes vitrales?", "a": "El gótico", "cat": "arte_literatura", "dif": "medio", "alias": ["Estilo gótico", "Arquitectura gótica", "Arte gótico"], "lz": "A"},
  {"n": 193, "q": "¿Qué movimiento artístico está asociado principalmente con Claude Monet y otros pintores interesados en captar los efectos cambiantes de la luz?", "a": "El impresionismo", "cat": "arte_literatura", "dif": "medio", "sabias": "El nombre viene del cuadro de Monet «Impresión, sol naciente», que un crítico usó en 1874 para burlarse del grupo.", "lz": "A"},
  {"n": 194, "q": "¿Quién escribió Moby-Dick?", "a": "Herman Melville", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 195, "q": "¿Qué filósofo griego desarrolló la teoría de las Ideas o Formas, según la cual las realidades sensibles son imperfectas respecto a realidades eternas e inmutables?", "a": "Platón", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 196, "q": "¿Qué conjunto monumental de Granada es famoso por el Patio de los Leones?", "a": "La Alhambra", "cat": "arte_literatura", "dif": "medio", "alias": ["Alhambra de Granada"], "lz": "B", "par": [205]},
  {"n": 198, "q": "¿Qué pintor renacentista italiano realizó La escuela de Atenas?", "a": "Rafael", "cat": "arte_literatura", "dif": "medio", "alias": ["Raphael"], "lz": "B"},
  {"n": 199, "q": "¿Qué escritor colombiano ganó el Premio Nobel de Literatura en 1982 y escribió Cien años de soledad?", "a": "Gabriel García Márquez", "cat": "arte_literatura", "dif": "medio", "sabias": "Nació en Aracataca, el pueblo que inspiró el Macondo de la novela.", "lz": "A"},
  {"n": 200, "q": "¿Qué famoso dramaturgo y poeta español del Siglo de Oro escribió Fuenteovejuna?", "a": "Lope de Vega", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 201, "q": "¿Qué novela de Umberto Eco está ambientada en una abadía medieval y gira alrededor de una serie de misteriosos asesinatos?", "a": "El nombre de la rosa", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 202, "q": "¿Qué escritora británica es la creadora de la famosa detective aficionada Miss Marple y del célebre investigador Hercule Poirot?", "a": "Agatha Christie", "cat": "arte_literatura", "dif": "medio", "sabias": "Su obra «La ratonera» se estrenó en Londres en 1952 y es la obra de teatro que más tiempo lleva en cartel.", "lz": "A"},
  {"n": 203, "q": "¿Qué novela de Mary Shelley, publicada en 1818, es considerada una de las obras fundacionales de la literatura de ciencia ficción?", "a": "Frankenstein", "cat": "arte_literatura", "dif": "dificil", "sabias": "La historia de Frankenstein surgió durante una competición amistosa de relatos de terror que Mary Shelley, Percy Bysshe Shelley y Lord Byron se propusieron escribir durante su estancia en Suiza en 1816.", "lz": "A"},
  {"n": 204, "q": "¿Qué movimiento literario europeo de finales del siglo XIX reaccionó contra ciertos aspectos del realismo y buscó una expresión más subjetiva y simbólica?", "a": "El simbolismo", "cat": "arte_literatura", "dif": "dificil", "sabias": "El simbolismo influyó especialmente en la poesía europea y en movimientos artísticos posteriores."},
  {"n": 205, "q": "¿Qué dinastía musulmana fue responsable de la construcción de la mayor parte de la Alhambra de Granada durante los siglos XIII y XIV?", "a": "Los nazaríes", "cat": "arte_literatura", "dif": "dificil", "sabias": "El nombre Alhambra procede del árabe al-Ḥamrāʾ, que significa «la roja», probablemente en referencia al color rojizo de sus murallas.", "alias": ["Dinastía nazarí", "Reino nazarí"], "lz": "B", "par": [196]},
  {"n": 206, "q": "¿Qué movimiento artístico de comienzos del siglo XX buscó representar el mundo mediante formas geométricas y múltiples puntos de vista?", "a": "El cubismo", "cat": "arte_literatura", "dif": "dificil", "sabias": "Picasso y Braque llegaron a representar simultáneamente distintas perspectivas de un mismo objeto.", "lz": "A"},
  {"n": 216, "q": "¿Quién compuso Las cuatro estaciones?", "a": "Antonio Vivaldi", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 217, "q": "¿Qué director dirigió El resplandor y La naranja mecánica?", "a": "Stanley Kubrick", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 218, "q": "¿Qué género cinematográfico se caracteriza por historias de detectives, crímenes, corrupción y ambientes oscuros, especialmente asociado al cine estadounidense de los años 40 y 50?", "a": "Cine negro", "cat": "arte_literatura", "dif": "medio", "alias": ["Film noir"], "lz": "B"},
  {"n": 219, "q": "¿Qué compositor austriaco es autor de óperas como Las bodas de Fígaro, Don Giovanni y La flauta mágica?", "a": "Wolfgang Amadeus Mozart", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 220, "q": "¿Qué compositor barroco compuso el famoso oratorio El Mesías, que incluye el conocido coro «Aleluya»?", "a": "Georg Friedrich Händel", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 221, "q": "¿Qué compositor italiano escribió la ópera La traviata?", "a": "Giuseppe Verdi", "cat": "arte_literatura", "dif": "medio", "sabias": "Verdi la basó en «La dama de las camelias», novela de Alexandre Dumas hijo, y se estrenó en 1853.", "lz": "A"},
  {"n": 222, "q": "¿Qué compositor escribió la música de la película El bueno, el feo y el malo?", "a": "Ennio Morricone", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 223, "q": "Según la UNESCO, ¿qué país produce más películas al año?", "a": "India", "cat": "arte_literatura", "dif": "medio", "lz": "B", "sabias": "La UNESCO contabilizó 1.907 largometrajes en la India en 2015."},
  {"n": 224, "q": "¿Qué cantante estadounidense fue conocida como la «Reina del Soul»?", "a": "Aretha Franklin", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 225, "q": "¿Qué cantante británica lanzó el álbum Back to Black en 2006?", "a": "Amy Winehouse", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 226, "q": "¿Qué icónica y futurista película de ciencia ficción de 1999, dirigida por las hermanas Wachowski, popularizó el efecto visual del bullet time?", "a": "Matrix", "cat": "arte_literatura", "dif": "medio", "sabias": "Popularizó el efecto bullet time, que congela la acción y permite girar la cámara alrededor de ella.", "alias": ["The Matrix"], "lz": "B"},
  {"n": 227, "q": "¿Qué película de Orson Welles, estrenada en 1941, suele aparecer entre las mejores películas de la historia y comienza con la palabra «Rosebud»?", "a": "Ciudadano Kane", "cat": "arte_literatura", "dif": "dificil", "sabias": "La película fue una de las primeras obras importantes de Orson Welles como director.", "alias": ["Citizen Kane"], "lz": "A"},
  {"n": 234, "q": "¿Qué prueba de atletismo combina siete disciplinas diferentes?", "a": "Heptatlón", "cat": "deporte", "dif": "medio", "sabias": "El heptatlón se disputa en dos jornadas y combina siete pruebas: 100 m vallas, salto de altura, lanzamiento de peso, 200 m, salto de longitud, jabalina y 800 m.", "lz": "A"},
  {"n": 235, "q": "¿Cuál de las tres grandes vueltas ciclistas se caracteriza por tener como color tradicional del maillot de líder el rosa?", "a": "Giro de Italia", "cat": "deporte", "dif": "medio", "sabias": "La maglia rosa imita el color rosa de las páginas del diario que organizó la carrera, La Gazzetta dello Sport.", "lz": "B"},
  {"n": 236, "q": "¿Qué nadador estadounidense consiguió ocho medallas de oro en los Juegos Olímpicos de Pekín 2008?", "a": "Michael Phelps", "cat": "deporte", "dif": "medio", "sabias": "Michael Phelps ganó las ocho pruebas que disputó en los Juegos de Pekín 2008 y estableció entonces un récord de ocho oros en una misma edición olímpica.", "lz": "A"},
  {"n": 237, "q": "¿Qué tenista masculino ha ganado más veces Roland Garros?", "a": "Rafael Nadal", "cat": "deporte", "dif": "medio", "sabias": "Rafael Nadal ganó 14 veces Roland Garros, un récord histórico en el torneo parisino y una de las mayores marcas de la historia del tenis.", "lz": "A"},
  {"n": 238, "q": "¿En qué deporte se disputa la Ryder Cup?", "a": "Golf", "cat": "deporte", "dif": "medio", "lz": "B"},
  {"n": 239, "q": "¿Qué país ganó el primer Mundial de fútbol en 1930?", "a": "Uruguay", "cat": "deporte", "dif": "medio", "sabias": "Fue anfitrión y campeón del primer Mundial, en 1930, tras vencer a Argentina en la final por 4-2.", "lz": "A"},
  {"n": 240, "q": "¿En qué deporte se utiliza un puck o disco?", "a": "Hockey sobre hielo", "cat": "deporte", "dif": "medio", "lz": "B"},
  {"n": 241, "q": "¿Qué piloto de Fórmula 1 fue conocido por el apodo de El Kaiser?", "a": "Michael Schumacher", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 242, "q": "¿Qué país ha ganado más medallas de oro en la historia de los Juegos Olímpicos de verano?", "a": "Estados Unidos", "cat": "deporte", "dif": "medio", "alias": ["EEUU", "EE. UU.", "USA", "Estados Unidos de América"], "lz": "B"},
  {"n": 243, "q": "¿Qué atleta jamaicano es famoso por sus récords mundiales en 100 y 200 metros?", "a": "Usain Bolt", "cat": "deporte", "dif": "medio", "sabias": "Sus récords mundiales son 9,58 s en los 100 m y 19,19 s en los 200 m, ambos logrados en Berlín 2009."},
  {"n": 244, "q": "¿Qué jugador es famoso por sus triples y fue MVP de la NBA en 2015 y 2016?", "a": "Stephen Curry", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 245, "q": "¿Cuántos jugadores forman un equipo de críquet en el campo durante un partido?", "a": "11", "cat": "deporte", "dif": "medio", "alias": ["Once"], "lz": "B"},
  {"n": 246, "q": "¿Qué ciclista estadounidense fue despojado de sus siete títulos del Tour de Francia por dopaje?", "a": "Lance Armstrong", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 247, "q": "¿Qué selección ha ganado más veces la Copa Mundial de rugby masculino?", "a": "Sudáfrica", "cat": "deporte", "dif": "medio", "alias": ["Springboks"], "lz": "A", "sabias": "Sudáfrica suma cuatro títulos (1995, 2007, 2019 y 2023) y Nueva Zelanda tres, hasta el Mundial de 2023."},
  {"n": 248, "q": "¿Qué ciclista español ganó cinco Tours de Francia consecutivos entre 1991 y 1995?", "a": "Miguel Induráin", "cat": "deporte", "dif": "medio", "sabias": "Fue el primer ciclista de la historia en ganar cinco Tours de Francia consecutivos.", "lz": "A"},
  {"n": 249, "q": "¿Qué boxeador estadounidense consiguió convertirse en campeón mundial de los pesos pesados a los 20 años, siendo el más joven en lograrlo en aquel momento?", "a": "Mike Tyson", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 250, "q": "¿Qué piloto brasileño ganó tres campeonatos del mundo de Fórmula 1 y murió durante el Gran Premio de San Marino de 1994?", "a": "Ayrton Senna", "cat": "deporte", "dif": "dificil", "sabias": "Senna ganó seis veces el Gran Premio de Mónaco, un récord que sigue vigente.", "lz": "A"},
  {"n": 261, "q": "¿Qué empresa adquirió Android Inc. en 2005 y posteriormente impulsó el sistema operativo Android?", "a": "Google", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 262, "q": "¿Qué dispositivo permite conectar varios dispositivos de una red local y dirigir los datos hacia otras redes, como Internet?", "a": "Un router (enrutador)", "cat": "cultura_general", "dif": "medio", "lz": "B"},
  {"n": 263, "q": "¿Qué lenguaje de programación es utilizado ampliamente en áreas como el análisis de datos, la inteligencia artificial y la automatización?", "a": "Python", "cat": "cultura_general", "dif": "medio", "sabias": "Su nombre rinde homenaje al grupo cómico Monty Python, no a la serpiente."},
  {"n": 264, "q": "¿Cómo se denomina el fraude que intenta obtener datos personales mediante mensajes o páginas web falsas que suplantan a una entidad legítima?", "a": "Phishing", "cat": "cultura_general", "dif": "medio", "sabias": "Suena igual que fishing, «pescar»: los estafadores lanzan el cebo y esperan a que alguien pique.", "lz": "A"},
  {"n": 265, "q": "¿Qué lenguaje se utiliza principalmente para estructurar el contenido de las páginas web?", "a": "HTML", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 266, "q": "¿Qué invento transmitió mensajes por señales eléctricas antes del teléfono?", "a": "El telégrafo", "cat": "cultura_general", "dif": "medio", "sabias": "Samuel Morse envió el primer mensaje público por telégrafo en 1844.", "alias": ["Telégrafo eléctrico"], "lz": "A"},
  {"n": 267, "q": "¿Qué nombre recibe la tecnología que permite pagar acercando una tarjeta o teléfono a un terminal compatible?", "a": "NFC", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 268, "q": "¿Qué unidad se utiliza para medir la velocidad de transmisión de datos en una red informática?", "a": "Bits por segundo (bit/s)", "cat": "cultura_general", "dif": "medio"},
  {"n": 269, "q": "¿Qué protocolo traduce nombres de dominio, como www.ejemplo.com, en direcciones IP?", "a": "DNS", "cat": "cultura_general", "dif": "medio", "alias": ["Protocolo DNS"], "lz": "A"},
  {"n": 270, "q": "¿Qué componente de un teléfono detecta principalmente los movimientos de rotación del dispositivo?", "a": "El giroscopio", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 271, "q": "¿Qué misión espacial llevó por primera vez seres humanos a la superficie de la Luna?", "a": "Apolo 11", "cat": "cultura_general", "dif": "medio", "sabias": "Apolo 11 aterrizó en el mar de la Tranquilidad en julio de 1969.", "alias": ["Apolo XI"], "lz": "B"},
  {"n": 272, "q": "¿Qué red mundial interconecta miles de millones de dispositivos en todo el mundo mediante el conjunto de protocolos TCP/IP?", "a": "Internet", "cat": "cultura_general", "dif": "medio"},
  {"n": 273, "q": "¿Qué red de ordenadores desarrollada en Estados Unidos a finales de los años 60 es considerada un antecedente fundamental de Internet?", "a": "ARPANET", "cat": "cultura_general", "dif": "dificil", "sabias": "El primer mensaje enviado por ARPANET en 1969 fue «LO», porque el sistema falló antes de completar «LOGIN».", "lz": "A"},
  {"n": 274, "q": "¿Qué nombre recibió el primer satélite artificial de la historia, lanzado por la Unión Soviética en 1957?", "a": "Sputnik 1", "cat": "cultura_general", "dif": "dificil", "sabias": "Sputnik 1 emitía señales de radio que podían captarse desde la Tierra.", "alias": ["Sputnik"], "lz": "B"},
  {"n": 289, "q": "¿Qué organización internacional tiene su sede principal en Nueva York y fue fundada en 1945?", "a": "La ONU", "cat": "cultura_general", "dif": "medio", "alias": ["Naciones Unidas"], "lz": "B"},
  {"n": 290, "q": "¿Qué metal precioso tiene el símbolo químico Ag?", "a": "La plata", "cat": "cultura_general", "dif": "medio", "sabias": "Su símbolo, Ag, viene del latín argentum, de donde procede también el nombre de Argentina.", "lz": "B"},
  {"n": 291, "q": "¿Cuál es la lengua individual con mayor número de hablantes nativos del mundo?", "a": "El chino mandarín", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 292, "q": "¿Qué indicador mide el valor total de los bienes y servicios finales producidos dentro de un país durante un periodo?", "a": "El Producto Interior Bruto (PIB)", "cat": "cultura_general", "dif": "medio", "alias": ["Producto Interno Bruto"], "lz": "B"},
  {"n": 293, "q": "¿Qué filósofo griego fue maestro de Alejandro Magno?", "a": "Aristóteles", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 294, "q": "¿Qué rama de la lingüística estudia el origen y la historia de las palabras?", "a": "La etimología", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 295, "q": "¿Qué continente tiene actualmente el mayor número de Estados soberanos?", "a": "África", "cat": "cultura_general", "dif": "medio", "lz": "B", "par": [297]},
  {"n": 296, "q": "¿Qué país fue el primero en conceder a las mujeres el derecho al voto en elecciones nacionales?", "a": "Nueva Zelanda", "cat": "cultura_general", "dif": "medio", "sabias": "Nueva Zelanda concedió el voto a las mujeres en 1893, casi tres décadas antes que Estados Unidos.", "lz": "A"},
  {"n": 297, "q": "¿Qué continente está atravesado por el ecuador y el meridiano de Greenwich, por lo que se extiende por los cuatro hemisferios?", "a": "África", "cat": "cultura_general", "dif": "medio", "lz": "B", "par": [295]},
  {"n": 298, "q": "¿Quién patentó el teléfono en 1876?", "a": "Alexander Graham Bell", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 299, "q": "¿Qué país regaló a Estados Unidos la Estatua de la Libertad?", "a": "Francia", "cat": "cultura_general", "dif": "medio", "sabias": "Gustave Eiffel diseñó su estructura interior de hierro, y Francia la regaló a Estados Unidos en 1886.", "lz": "B"},
  {"n": 300, "q": "¿Quién lideró la expedición que inició la primera circunnavegación de la Tierra, completada por Juan Sebastián Elcano?", "a": "Fernando de Magallanes", "cat": "cultura_general", "dif": "medio", "sabias": "Murió en Filipinas en 1521; fue Elcano quien completó la primera vuelta al mundo en 1522.", "lz": "A"},
  {"n": 301, "q": "¿Qué batalla naval de 1571 enfrentó a la Liga Santa contra el Imperio otomano y frenó su expansión en el Mediterráneo occidental?", "a": "La batalla de Lepanto", "cat": "historia", "dif": "dificil", "sabias": "La batalla de Lepanto tuvo lugar el 7 de octubre de 1571 y fue una de las mayores batallas navales de la Edad Moderna.", "lz": "A"},
  {"n": 302, "q": "¿Qué emperador romano promulgó en el siglo III la Constitutio Antoniniana, que extendió la ciudadanía romana a casi todos los hombres libres del Imperio?", "a": "Caracalla", "cat": "historia", "dif": "dificil", "sabias": "La Constitutio Antoniniana fue promulgada en el año 212 y amplió enormemente el número de ciudadanos romanos.", "alias": ["Emperador Caracalla"], "lz": "A"},
  {"n": 303, "q": "¿Qué zar ruso abolió la servidumbre en 1861 mediante una de las principales reformas del Imperio ruso?", "a": "Alejandro II", "cat": "historia", "dif": "dificil", "sabias": "La emancipación de 1861 liberó jurídicamente a millones de campesinos siervos del Imperio ruso.", "lz": "A"},
  {"n": 304, "q": "¿Qué país contiene el salar de Uyuni, la mayor planicie salina continua del mundo?", "a": "Bolivia", "cat": "geografia", "dif": "dificil", "sabias": "El salar de Uyuni ocupa unos 10.000 kilómetros cuadrados y se formó a partir de antiguos lagos prehistóricos.", "lz": "A"},
  {"n": 305, "q": "¿Qué fenómeno explica que un reloj en movimiento respecto de un observador marche más lentamente según la relatividad especial?", "a": "La dilatación temporal", "cat": "ciencia", "dif": "dificil", "sabias": "La dilatación temporal se hace apreciable a velocidades cercanas a la velocidad de la luz y ha sido confirmada experimentalmente con relojes atómicos.", "alias": ["Dilatación del tiempo"], "lz": "B"},
  {"n": 306, "q": "¿Qué estructura del ADN propusieron Watson y Crick en 1953 a partir, entre otras evidencias, de datos de difracción de rayos X?", "a": "La doble hélice", "cat": "ciencia", "dif": "dificil", "sabias": "Los trabajos de Rosalind Franklin y Maurice Wilkins aportaron datos de difracción de rayos X fundamentales para comprender la estructura del ADN.", "lz": "B"},
  {"n": 307, "q": "¿Qué tragedia de Shakespeare presenta a los personajes Rosencrantz y Guildenstern?", "a": "Hamlet", "cat": "arte_literatura", "dif": "dificil", "sabias": "Rosencrantz y Guildenstern son antiguos conocidos de Hamlet a quienes Claudio encarga vigilar al príncipe.", "lz": "A"},
  {"n": 308, "q": "¿Qué lengua es la única lengua semítica que es lengua oficial de la Unión Europea?", "a": "El maltés", "cat": "cultura_general", "dif": "dificil", "sabias": "El maltés es una lengua semítica estrechamente relacionada con las variedades árabes históricas de Sicilia y el norte de África, pero utiliza el alfabeto latino.", "alias": ["Idioma maltés", "Lengua maltesa"], "lz": "A"},
  {"n": 309, "q": "¿Qué empresa creó el lenguaje de programación Java originalmente bajo el proyecto Green?", "a": "Sun Microsystems", "cat": "cultura_general", "dif": "dificil", "sabias": "Java se llamó inicialmente Oak durante su desarrollo y fue diseñado con la idea de permitir ejecutar programas en distintos tipos de dispositivos.", "lz": "A"},
  {"n": 310, "q": "¿Qué tenista fue la primera en completar el Golden Slam, ganando los cuatro torneos de Grand Slam y el oro olímpico en un mismo año?", "a": "Steffi Graf", "cat": "deporte", "dif": "dificil", "sabias": "Steffi Graf logró en 1988 lo que ningún otro tenista de pista ha conseguido ni antes ni después.", "lz": "A"},
  {"n": 311, "q": "¿Qué país cuenta con la mayor cantidad de islas del mundo en su territorio?", "a": "Suecia", "cat": "geografia", "dif": "dificil", "sabias": "Según el recuento oficial sueco, supera las 260.000 islas, la mayoría muy pequeñas."},
  {"n": 312, "q": "¿Qué estructura cerebral desempeña un papel fundamental en la consolidación de nuevos recuerdos?", "a": "Hipocampo", "cat": "ciencia", "dif": "dificil", "sabias": "El hipocampo no almacena por sí solo todos los recuerdos a largo plazo, pero es esencial para su formación y consolidación.", "lz": "A"},
  {"n": 313, "q": "¿Qué científico fue el primero en observar células utilizando un microscopio y acuñó el término «célula»?", "a": "Robert Hooke", "cat": "ciencia", "dif": "dificil", "sabias": "Hooke utilizó el término «célula» al observar pequeñas cavidades en una lámina de corcho en 1665.", "lz": "A"},
  {"n": 314, "q": "¿Qué fenómeno permite que una estrella pueda producir energía mediante la transformación de hidrógeno en helio?", "a": "Fusión nuclear", "cat": "ciencia", "dif": "dificil", "sabias": "El Sol convierte cada segundo unos 600 millones de toneladas de hidrógeno en helio.", "lz": "A"},
  {"n": 315, "q": "¿Qué director japonés dirigió Los siete samuráis?", "a": "Akira Kurosawa", "cat": "arte_literatura", "dif": "dificil", "sabias": "La película de 1954 influyó enormemente en el cine occidental y fue posteriormente adaptada en distintas formas, incluida Los siete magníficos.", "lz": "A"},
  {"n": 316, "q": "¿Qué película ganó el primer Óscar a la mejor película en 1929?", "a": "Wings", "cat": "arte_literatura", "dif": "dificil", "sabias": "Wings es una película muda centrada en dos pilotos durante la Primera Guerra Mundial. Sunrise ganó en esa ceremonia un premio distinto, el de producción única y artística."},
  {"n": 317, "q": "¿Qué famoso protocolo internacional firmado en 1987 se adoptó para proteger la capa de ozono prohibiendo las sustancias que la agotan?", "a": "El Protocolo de Montreal", "cat": "cultura_general", "dif": "dificil", "sabias": "Está considerado como uno de los acuerdos ambientales internacionales más exitosos de la historia, logrando la reducción casi total de los clorofluorocarbonos (CFC).", "lz": "A"},
  {"n": 318, "q": "¿Qué conflicto medieval, iniciado en 1337, enfrentó a Inglaterra y Francia de forma intermitente durante más de un siglo por la sucesión al trono francés?", "a": "La guerra de los Cien Años", "cat": "historia", "dif": "dificil", "sabias": "Pese a su nombre, el conflicto se prolongó realmente 116 años, entre 1337 y 1453, y en él destacó la figura de Juana de Arco.", "lz": "A"},
  {"n": 319, "q": "¿Qué velocista y saltador estadounidense ganó nueve oros olímpicos entre 1984 y 1996?", "a": "Carl Lewis", "cat": "deporte", "dif": "dificil", "sabias": "Carl Lewis ganó el oro en salto de longitud en cuatro Juegos Olímpicos consecutivos, de 1984 a 1996, un logro excepcional en la historia olímpica.", "lz": "A"},
  {"n": 320, "q": "¿Qué institución establece la política monetaria de la zona euro y tiene como objetivo principal mantener la estabilidad de precios?", "a": "Banco Central Europeo", "cat": "cultura_general", "dif": "dificil", "sabias": "El Banco Central Europeo, junto con los bancos centrales nacionales de los países de la zona euro, forma el Eurosistema y dirige la política monetaria del euro.", "alias": ["BCE"], "lz": "B"},
  {"n": 325, "q": "¿Qué país ganó la primera Copa Mundial de fútbol femenino de la FIFA, disputada en 1991?", "a": "Estados Unidos", "cat": "deporte", "dif": "medio", "alias": ["EEUU", "EE. UU.", "USA", "Estados Unidos de América"], "lz": "B"},
  {"n": 326, "q": "¿Qué tenista ganó cinco veces consecutivas el torneo de Wimbledon entre 1976 y 1980?", "a": "Björn Borg", "cat": "deporte", "dif": "medio", "sabias": "Borg ganó cinco Wimbledon seguidos, de 1976 a 1980; en 1981 McEnroe le cortó la racha en la final.", "lz": "A"},
  {"n": 327, "q": "¿Qué golfista estadounidense ganó cinco veces el Masters de Augusta?", "a": "Tiger Woods", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 328, "q": "¿Qué piloto español ganó los Campeonatos del Mundo de Fórmula 1 de 2005 y 2006?", "a": "Fernando Alonso", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 329, "q": "¿Qué boxeador estadounidense ganó el oro olímpico en peso semipesado en 1960 antes de convertirse en campeón mundial de los pesos pesados?", "a": "Muhammad Ali", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 330, "q": "¿Qué jugadora fue la primera española en jugar en la WNBA?", "a": "Amaya Valdemoro", "cat": "deporte", "dif": "medio"},
  {"n": 331, "q": "¿Cuáles son las tres armas utilizadas en la esgrima olímpica?", "a": "Florete, espada y sable", "cat": "deporte", "dif": "medio", "lz": "B"},
  {"n": 332, "q": "¿En qué deporte se deslizan piedras de granito sobre una pista de hielo mientras los jugadores barren delante de ellas?", "a": "Curling", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 333, "q": "¿Qué atleta sudafricano fue el primer corredor con dos piernas amputadas en competir en unos Juegos Olímpicos?", "a": "Oscar Pistorius", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 334, "q": "¿Cómo se llama en baloncesto la falta por protestar a los árbitros o por mala conducta, aunque no haya contacto?", "a": "Falta técnica", "cat": "deporte", "dif": "medio"},
  {"n": 335, "q": "¿Cuántas vueltas a una pista de 400 m son los 1.500 m lisos?", "a": "3,75 vueltas", "cat": "deporte", "dif": "medio"},
  {"n": 336, "q": "¿Qué ciclista italiano consiguió ganar al menos una vez las tres grandes vueltas por etapas: Tour de Francia, Giro de Italia y Vuelta a España?", "a": "Vincenzo Nibali", "cat": "deporte", "dif": "dificil", "sabias": "Vincenzo Nibali completó ese particular «triple» al ganar la Vuelta a España en 2010, el Giro de Italia en 2013 y 2016, y el Tour de Francia en 2014."},
  {"n": 338, "q": "¿Qué tratado firmado en 1840 entre representantes de la Corona británica y numerosos jefes maoríes es considerado el documento fundacional de Nueva Zelanda?", "a": "Tratado de Waitangi", "cat": "historia", "dif": "medio", "sabias": "El tratado se redactó en inglés y en maorí, y las dos versiones no decían exactamente lo mismo, algo que sigue generando debate.", "lz": "A"},
  {"n": 339, "q": "¿Qué importante reunión internacional celebrada entre 1814 y 1815 rediseñó el mapa político de Europa tras la caída de Napoleón Bonaparte y restauró el Antiguo Régimen en varias monarquías?", "a": "Congreso de Viena", "cat": "historia", "dif": "medio", "sabias": "El Congreso de Viena intentó establecer un nuevo equilibrio europeo después de las guerras napoleónicas y reunió a representantes de las principales potencias entre 1814 y 1815.", "lz": "A"},
  {"n": 340, "q": "¿Cómo se denominó el sistema de segregación racial institucionalizado en Sudáfrica desde 1948 hasta principios de la década de 1990?", "a": "Apartheid", "cat": "historia", "dif": "medio", "sabias": "Apartheid significa «separación» en afrikáans: clasificaba a las personas por raza y decidía dónde podían vivir, trabajar o estudiar. Sus leyes se derogaron a principios de los 90 y en 1994 hubo elecciones multirraciales.", "lz": "A"},
  {"n": 341, "q": "¿Qué ciudad italiana se considera la cuna del Renacimiento?", "a": "Florencia", "cat": "historia", "dif": "medio", "sabias": "Los Médici, banqueros florentinos, protegieron a artistas como Botticelli y Donatello.", "lz": "B", "alias": ["Florencia (Italia)"]},
  {"n": 342, "q": "¿Qué líder bolchevique dirigió la Revolución de Octubre de 1917 y se convirtió en el primer jefe de gobierno de la Rusia soviética?", "a": "Vladímir Lenin", "cat": "historia", "dif": "medio", "sabias": "Lenin dirigió el gobierno soviético hasta su muerte en 1924; su sucesión desató una lucha de poder que ganó Stalin.", "lz": "B"},
  {"n": 346, "q": "¿Qué país tiene tres capitales oficiales: Pretoria, Ciudad del Cabo y Bloemfontein?", "a": "Sudáfrica", "cat": "geografia", "dif": "medio", "sabias": "Se reparten los poderes: Pretoria es la sede del gobierno, Ciudad del Cabo del parlamento y Bloemfontein de la justicia.", "lz": "A"},
  {"n": 347, "q": "¿Qué país europeo, conocido por su forma alargada a lo largo del mar Adriático, tiene su capital en Zagreb?", "a": "Croacia", "cat": "geografia", "dif": "medio", "lz": "B"},
  {"n": 348, "q": "¿Cuál es el pico más alto de la cordillera de los Alpes y de toda Europa occidental, situado en la frontera entre Francia e Italia?", "a": "El Mont Blanc", "cat": "geografia", "dif": "medio", "lz": "A"},
  {"n": 349, "q": "¿Cuál es la meseta de mayor altitud y extensión del mundo, a menudo denominada «el techo del mundo» debido a su relieve elevado rodeado por imponentes cordilleras como el Himalaya?", "a": "Meseta del Tíbet", "cat": "geografia", "dif": "dificil", "sabias": "La meseta tibetana se encuentra a una altitud media superior a los 4.500 metros sobre el nivel del mar y su enorme masa terrestre influye de manera determinante en los patrones climáticos globales de los monzones asiáticos.", "alias": ["Altiplano del Tíbet", "Altiplano tibetano"], "lz": "B"},
  {"n": 350, "q": "¿Qué científico propuso en 1912 la teoría de la deriva continental?", "a": "Alfred Wegener", "cat": "ciencia", "dif": "medio", "sabias": "Su idea de que los continentes se desplazan fue rechazada durante décadas; no se aceptó hasta que apareció la tectónica de placas en los años 60.", "lz": "A"},
  {"n": 351, "q": "¿Qué tipo de ARN transporta aminoácidos hasta el ribosoma durante la síntesis de proteínas?", "a": "ARN de transferencia", "cat": "ciencia", "dif": "medio", "alias": ["ARNt"], "lz": "B"},
  {"n": 352, "q": "¿Cómo se llaman los vasos que llevan la sangre desde el corazón al resto del cuerpo?", "a": "Arterias", "cat": "ciencia", "dif": "medio", "sabias": "Llevan la sangre desde el corazón hacia los tejidos; la mayoría transporta sangre oxigenada, pero las arterias pulmonares llevan sangre pobre en oxígeno a los pulmones.", "lz": "B"},
  {"n": 353, "q": "¿Cómo se denomina el proceso geológico mediante el cual los sedimentos sueltos se compactan y cementan hasta formar una roca sedimentaria?", "a": "Litificación", "cat": "ciencia", "dif": "dificil", "sabias": "Durante la litificación, la presión puede compactar los sedimentos y los minerales disueltos en el agua pueden actuar como cemento, uniendo los granos hasta formar una roca."},
  {"n": 354, "q": "¿Cómo se denomina el fenómeno físico en el que un material expuesto a temperaturas extremadamente bajas pierde completamente su resistencia eléctrica?", "a": "Superconductividad", "cat": "ciencia", "dif": "dificil", "sabias": "Descubierta en 1911 por el físico Heike Kamerlingh Onnes al enfriar mercurio con helio líquido, la superconductividad permite que la corriente eléctrica fluya indefinidamente sin disipar energía en forma de calor.", "lz": "A"},
  {"n": 355, "q": "¿Qué civilización mesoamericana utilizó un sistema de numeración vigesimal y desarrolló de forma independiente el concepto del cero?", "a": "Maya", "cat": "cultura_general", "dif": "medio", "sabias": "Los mayas utilizaron el cero de forma independiente, siglos antes de que se difundiera por Europa.", "alias": ["Civilización maya"], "lz": "A"},
  {"n": 356, "q": "¿Qué sistema internacional de identificación numérica se utiliza para identificar de forma única las ediciones de libros?", "a": "ISBN", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 357, "q": "¿Qué sistema de escritura táctil, basado en puntos en relieve grabados en papel, permite leer y escribir a las personas ciegas o con deficiencia visual grave?", "a": "Sistema Braille", "cat": "cultura_general", "dif": "medio", "sabias": "Louis Braille lo inventó con solo 15 años, en 1824, y era ciego desde la infancia.", "lz": "A"},
  {"n": 358, "q": "¿Qué premio estadounidense, administrado por la Universidad de Columbia, reconoce el periodismo, la literatura y la música?", "a": "Los Premios Pulitzer", "cat": "cultura_general", "dif": "medio", "lz": "A"},
  {"n": 359, "q": "¿Qué instrumento de teclado barroco, de cuerdas pulsadas con plectros, fue precursor del piano?", "a": "Clavecín", "cat": "arte_literatura", "dif": "facil", "sabias": "Bartolomeo Cristofori inventó el piano hacia 1700.", "alias": ["Clavicémbalo"], "lz": "B"},
  {"n": 360, "q": "¿Qué famosa escritora británica es la creadora del célebre universo literario y de la exitosa saga de novelas fantásticas protagonizadas por el joven mago Harry Potter?", "a": "J. K. Rowling", "cat": "arte_literatura", "dif": "medio", "lz": "A"},
  {"n": 363, "q": "¿En qué país se originó el taekwondo moderno?", "a": "Corea del Sur", "cat": "deporte", "dif": "medio", "sabias": "El taekwondo apareció como deporte de exhibición en los Juegos Olímpicos de Seúl 1988 y Barcelona 1992 antes de convertirse en deporte olímpico oficial en Sídney 2000.", "lz": "A"},
  {"n": 366, "q": "¿Qué famosa competición de motociclismo se disputa en un circuito formado principalmente por carreteras públicas de la Isla de Man?", "a": "Isle of Man TT", "cat": "deporte", "dif": "dificil", "sabias": "El Mountain Course del TT recorre más de 60 kilómetros y utiliza carreteras que forman parte de la red viaria pública de la Isla de Man.", "lz": "B"},
  {"n": 370, "q": "En las reglas habituales del baloncesto, ¿cuál es el tiempo máximo de posesión para intentar un lanzamiento a canasta tras obtener el control del balón del equipo contrario?", "a": "24 segundos", "cat": "deporte", "dif": "medio", "sabias": "El reloj de posesión puede reiniciarse a 14 segundos en determinadas situaciones, como cuando el mismo equipo recupera el balón tras un lanzamiento que toca el aro.", "alias": ["24","veinticuatro"], "lz": "A"},
  {"n": 371, "q": "¿En qué deporte se utiliza un aparato conocido como «caballo con arcos»?", "a": "Gimnasia artística", "cat": "deporte", "dif": "medio", "lz": "A"},
  {"n": 372, "q": "¿En qué país se inventó el juego del pádel a finales de la década de 1960?", "a": "México", "cat": "deporte", "dif": "medio", "sabias": "Enrique Corcuera creó la primera pista de pádel en Acapulco en 1969, adaptando el juego al espacio disponible en su casa.", "lz": "A"},
  {"n": 322, "q": "¿Qué atleta estadounidense ganó cuatro medallas de oro en los Juegos Olímpicos de Berlín de 1936?", "a": "Jesse Owens", "cat": "deporte", "dif": "facil", "sabias": "Ganó en Berlín 1936 los 100 m, los 200 m, el salto de longitud y el relevo 4×100, en unos Juegos pensados para exaltar la propaganda nazi.", "lz": "B"},
  {"n": 324, "q": "¿Cómo se llama en golf meter la bola en el hoyo de un solo golpe desde el tee?", "a": "Hoyo en uno", "cat": "deporte", "dif": "facil", "lz": "B", "alias": ["Hole in one"]},
  {"n": 364, "q": "¿Qué deporte combina esquí de fondo y tiro con rifle?", "a": "Biatlón", "cat": "deporte", "dif": "facil", "sabias": "El biatlón tiene sus raíces en antiguas tradiciones militares de los países nórdicos, donde esquiar y disparar podía ser una habilidad necesaria.", "lz": "B"},
  {"n": 374, "q": "¿Qué gran río asiático atraviesa China y varios países del Sudeste Asiático?", "a": "Mekong", "cat": "geografia", "dif": "medio", "alias": ["Río Mekong"], "lz": "A"},
  {"n": 375, "q": "¿Cómo se denomina la extensa llanura fértil que ocupa gran parte del centro y este de Argentina?", "a": "Pampas", "cat": "geografia", "dif": "medio", "alias": ["Llanura pampeana"], "lz": "A"},
  {"n": 376, "q": "¿Cuál es la cordillera más larga del mundo en tierra firme?", "a": "Andes", "cat": "geografia", "dif": "medio", "sabias": "Los Andes se extienden por unos 7.000 kilómetros a lo largo del borde occidental de Sudamérica.", "alias": ["Cordillera de los Andes"], "lz": "B"},
  {"n": 377, "q": "¿Cómo se denomina una línea de un mapa que une puntos de igual altitud?", "a": "Curva de nivel", "cat": "geografia", "dif": "medio", "lz": "B"},
  {"n": 378, "q": "¿Cómo se denomina el proceso por el que aumenta la proporción de población que vive en ciudades?", "a": "Urbanización", "cat": "geografia", "dif": "medio", "lz": "B"},
  {"n": 379, "q": "¿Cuál es la capital de Mongolia?", "a": "Ulán Bator", "cat": "geografia", "dif": "medio", "alias": ["Ulaanbaatar"], "lz": "B"},
  {"n": 381, "q": "¿Cuál es el país sin salida al mar más extenso del mundo?", "a": "Kazajistán", "cat": "geografia", "dif": "dificil", "sabias": "Aunque no tiene costa oceánica, Kazajistán limita con el mar Caspio, que es un enorme cuerpo de agua interior.", "lz": "A"},
  {"n": 383, "q": "¿Qué canal artificial de navegación une el mar Rojo con el mar Mediterráneo a través de Egipto?", "a": "Canal de Suez", "cat": "geografia", "dif": "medio", "sabias": "El canal fue inaugurado oficialmente el 17 de noviembre de 1869 y tiene aproximadamente 193 kilómetros de longitud.", "lz": "B", "par": [87]},
  {"n": 385, "q": "¿Cómo se denomina la relación ecológica en la que ambas especies obtienen un beneficio?", "a": "Mutualismo", "cat": "ciencia", "dif": "medio", "sabias": "La relación entre muchas plantas con flores y sus polinizadores es un ejemplo de mutualismo: la planta puede reproducirse y el animal obtiene alimento.", "lz": "A"},
  {"n": 387, "q": "¿Qué sustancia forma una vaina alrededor de muchos axones y aumenta la velocidad de transmisión de los impulsos nerviosos?", "a": "Mielina", "cat": "ciencia", "dif": "dificil", "alias": ["Vaina de mielina"], "lz": "A"},
  {"n": 388, "q": "¿Cómo se denomina el proceso por el que los restos o huellas de organismos quedan preservados en el registro geológico?", "a": "Fosilización", "cat": "ciencia", "dif": "medio", "lz": "B"},
  {"n": 389, "q": "¿Cómo se denominan las rocas formadas cuando el magma o la lava se enfrían y solidifican?", "a": "Ígneas", "cat": "ciencia", "dif": "medio", "alias": ["Rocas ígneas"], "lz": "B"},
  {"n": 390, "q": "¿Qué componentes de la sangre desempeñan un papel fundamental en la coagulación?", "a": "Plaquetas", "cat": "ciencia", "dif": "medio", "alias": ["Trombocitos"], "lz": "A"},
  {"n": 391, "q": "¿Qué parte del ojo regula la cantidad de luz que entra en él?", "a": "El iris", "cat": "ciencia", "dif": "medio", "sabias": "El iris modifica el tamaño de la pupila, que funciona como una abertura reguladora de la luz.", "lz": "A"},
  {"n": 392, "q": "¿Qué gas noble, incoloro e inodoro, es el más pesado de los gases nobles estables presentes en la atmósfera y se emplea, entre otras aplicaciones, en iluminación?", "a": "Xenón", "cat": "ciencia", "dif": "medio", "lz": "A"},
  {"n": 393, "q": "¿Qué tipo de enlaces químicos se forman cuando los átomos comparten pares de electrones de su capa externa?", "a": "Enlaces covalentes", "cat": "ciencia", "dif": "medio", "lz": "B"},
  {"n": 394, "q": "¿Cómo se llama la región exterior y extremadamente tenue de la atmósfera del Sol, que se extiende millones de kilómetros en el espacio y se vuelve especialmente visible durante un eclipse solar total?", "a": "Corona solar", "cat": "ciencia", "dif": "dificil", "sabias": "La corona solar puede alcanzar temperaturas de varios millones de grados Celsius, a pesar de que la fotosfera, la superficie visible del Sol, está a unos 5.500 °C. Este extraordinario calentamiento de la corona sigue siendo un importante problema de la física solar.", "lz": "A"},
  {"n": 395, "q": "¿Cómo se llama el punto de una órbita alrededor de la Tierra en el que un satélite o la Luna se encuentra a la mayor distancia posible de nuestro planeta?", "a": "Apogeo", "cat": "ciencia", "dif": "dificil", "lz": "A"},
  {"n": 396, "q": "¿Qué fenómeno mide la escala de Richter?", "a": "La magnitud de los terremotos", "cat": "ciencia", "dif": "medio", "sabias": "La escala de Richter fue desarrollada por el sismólogo Charles Richter en 1935 para medir la magnitud de los terremotos."},
  {"n": 397, "q": "¿Cómo se llama el telescopio espacial, fruto de la colaboración de la NASA, la ESA y la Agencia Espacial Canadiense, que fue lanzado en diciembre de 2021 y observa sobre todo en infrarrojo?", "a": "Telescopio Espacial James Webb", "cat": "ciencia", "dif": "dificil", "sabias": "El Webb no sustituye al Hubble: lo complementa. Mientras el Hubble observa sobre todo en luz visible y ultravioleta, el Webb está diseñado para el infrarrojo, lo que le permite estudiar objetos muy lejanos y ver a través de algunas nubes de polvo.", "lz": "A"},
  {"n": 398, "q": "¿Qué unidad del Sistema Internacional se emplea para medir la presión?", "a": "Pascal", "cat": "ciencia", "dif": "medio", "sabias": "Un pascal equivale a un newton por metro cuadrado.", "alias": ["Pa"], "lz": "A"},
  {"n": 400, "q": "¿Qué neurólogo austriaco es considerado el padre del psicoanálisis?", "a": "Sigmund Freud", "cat": "cultura_general", "dif": "medio", "sabias": "Publicó «La interpretación de los sueños» en 1899, aunque en la portada figura 1900.", "lz": "A"},
  {"n": 402, "q": "¿Cómo se denomina la red ferroviaria de alta velocidad de Japón, inaugurada en 1964?", "a": "Shinkansen", "cat": "cultura_general", "dif": "medio", "sabias": "El primer Shinkansen comenzó a funcionar en 1964, el mismo año en que Tokio acogió los Juegos Olímpicos.", "lz": "A"},
  {"n": 403, "q": "¿Qué inventor e ingeniero serbio-estadounidense es conocido por sus contribuciones al desarrollo de los sistemas de corriente alterna?", "a": "Nikola Tesla", "cat": "cultura_general", "dif": "medio", "sabias": "Tesla trabajó en distintos sistemas eléctricos y su nombre quedó asociado a la unidad del Sistema Internacional de inducción magnética, el tesla.", "lz": "A"},
  {"n": 404, "q": "¿Cómo se denominan los caracteres de origen chino utilizados en la escritura japonesa junto con los kana?", "a": "Kanji", "cat": "cultura_general", "dif": "medio", "sabias": "La palabra «kanji» significa literalmente «caracteres de Han», en referencia a la dinastía china Han.", "lz": "A"},
  {"n": 405, "q": "¿Cómo se denomina la fase cálida del fenómeno climático océano-atmosférico ENSO, caracterizada por un calentamiento anómalo de las aguas superficiales del Pacífico ecuatorial central y oriental?", "a": "El Niño", "cat": "ciencia", "dif": "medio", "sabias": "El Niño aparece de forma irregular cada pocos años y puede alterar los patrones de lluvia y temperatura en regiones muy alejadas del Pacífico.", "alias": ["Fenómeno de El Niño"], "lz": "A"},
  {"n": 406, "q": "¿Cómo se denomina la red de pagos entre pares y forma de dinero digital descentralizado cuya creación se atribuye al pseudónimo Satoshi Nakamoto?", "a": "Bitcoin", "cat": "cultura_general", "dif": "medio", "sabias": "El documento que presentó Bitcoin en 2008 proponía enviar pagos directamente entre personas sin necesidad de una institución financiera central.", "lz": "A"},
  {"n": 409, "q": "¿Cómo se llama uno de los principales dioses de la mitología nórdica, padre de Thor y Baldr, conocido por haber sacrificado uno de sus ojos a cambio de sabiduría?", "a": "Odín", "cat": "cultura_general", "dif": "medio", "sabias": "En la mitología nórdica, Odín aparece asociado no solo a la guerra, sino también a la sabiduría, la poesía, la magia y la muerte.", "lz": "A"},
  {"n": 410, "q": "¿Qué nombre recibe el software malicioso que recopila de forma clandestina información sobre la actividad de un usuario en un ordenador sin su consentimiento?", "a": "Spyware", "cat": "cultura_general", "dif": "medio", "sabias": "El spyware puede recopilar información sin que el usuario sea consciente de ello y, según el tipo, registrar hábitos de navegación, credenciales u otros datos.", "alias": ["Programa espía"], "lz": "B"},
  {"n": 411, "q": "¿Qué rey de Babilonia es famoso por un antiguo código de leyes que lleva su nombre?", "a": "Hammurabi", "cat": "historia", "dif": "medio", "sabias": "La famosa estela de Hammurabi mide más de dos metros de altura y está escrita principalmente en escritura cuneiforme.", "alias": ["Rey Hammurabi"], "lz": "A"},
  {"n": 412, "q": "¿Qué líder militar y político fue la principal figura de la Revolución cubana que derrocó al régimen de Fulgencio Batista en 1959?", "a": "Fidel Castro", "cat": "historia", "dif": "medio", "lz": "A", "sabias": "Entró victorioso en La Habana en enero de 1959, tras dos años de guerra de guerrillas."},
  {"n": 413, "q": "¿Quién fue el primer emperador de los franceses?", "a": "Napoleón Bonaparte", "cat": "historia", "dif": "medio", "sabias": "Se coronó en Notre-Dame en diciembre de 1804 y lo hizo él mismo: tomó la corona de manos del papa Pío VII y se la colocó en la cabeza.", "lz": "A"},
  {"n": 8, "q": "¿Qué científica polaca-francesa, pionera en el estudio de la radiactividad, recibió el Premio Nobel de Física en 1903 y el de Química en 1911?", "a": "Marie Curie", "cat": "historia", "dif": "facil", "sabias": "Marie Curie fue la primera persona en recibir dos Premios Nobel y sigue siendo la única mujer galardonada con dos Nobel en categorías científicas distintas.", "lz": "B"},
  {"n": 9, "q": "¿En qué año tuvo lugar el desembarco de Normandía?", "a": "1944", "cat": "historia", "dif": "facil", "sabias": "El desembarco de Normandía comenzó el 6 de junio de 1944 y movilizó a casi 160.000 soldados aliados en el primer día de la invasión.", "lz": "B"},
  {"n": 13, "q": "¿Qué faraón egipcio tuvo una tumba casi intacta descubierta por Howard Carter?", "a": "Tutankamón", "cat": "historia", "dif": "facil", "sabias": "Howard Carter descubrió la tumba de Tutankamón en 1922 y su extraordinario estado de conservación convirtió el hallazgo en uno de los descubrimientos arqueológicos más famosos del siglo XX.", "lz": "B"},
  {"n": 18, "q": "¿Qué antigua ciudad romana quedó sepultada bajo cenizas y piedra pómez tras la erupción del Vesubio del año 79 d. C. y es hoy uno de los yacimientos arqueológicos más conocidos de Italia?", "a": "Pompeya", "cat": "historia", "dif": "facil", "sabias": "La erupción del Vesubio del año 79 sepultó Pompeya y otras poblaciones cercanas bajo cenizas y materiales volcánicos, conservando edificios y objetos durante siglos.", "lz": "B"},
  {"n": 20, "q": "¿Qué líder sudafricano pasó 27 años en prisión antes de convertirse en presidente del país en 1994?", "a": "Nelson Mandela", "cat": "historia", "dif": "facil", "sabias": "Nelson Mandela pasó 27 años encarcelado y, tras su liberación en 1990, se convirtió en 1994 en el primer presidente negro de Sudáfrica elegido en unas elecciones democráticas.", "lz": "B"},
  {"n": 337, "q": "¿Qué ciudad fue la capital del Imperio bizantino durante más de mil años?", "a": "Constantinopla", "cat": "historia", "dif": "facil", "sabias": "Constantinopla fue durante siglos una de las ciudades más importantes del mundo y capital del Imperio bizantino hasta su conquista por los otomanos en 1453.", "lz": "B", "par": [44]},
  {"n": 414, "q": "¿Qué gran escritor ruso es el autor de las monumentales novelas «Guerra y paz» y «Ana Karénina»?", "a": "Lev Tolstói", "cat": "arte_literatura", "dif": "medio", "sabias": "Tolstói y Mahatma Gandhi mantuvieron correspondencia en 1909. Gandhi había estudiado sus escritos y afirmó que habían dejado una profunda impresión en él; ambos compartían un gran interés por la resistencia no violenta.", "lz": "A"},
  {"n": 417, "q": "¿Quién pintó la obra «La persistencia de la memoria», famosa por sus relojes blandos?", "a": "Salvador Dalí", "cat": "arte_literatura", "dif": "medio", "sabias": "Dalí pintó la obra en 1931 y convirtió los relojes blandos en uno de los símbolos más reconocibles del surrealismo.", "lz": "A"},
  {"n": 419, "q": "¿Qué país alberga la mayor superficie de selva amazónica?", "a": "Brasil", "cat": "geografia", "dif": "medio", "sabias": "La Amazonia se extiende por varios países sudamericanos, pero Brasil concentra aproximadamente el 60 % de su superficie.", "lz": "B"},
  {"n": 56, "q": "¿Cuál es la capital de Australia?", "a": "Canberra", "cat": "geografia", "dif": "facil", "sabias": "Canberra se eligió como capital en 1908 y se construyó desde cero como solución a la rivalidad entre Sídney y Melbourne.", "lz": "B"},
  {"n": 380, "q": "¿Cuál es la capital de Eslovaquia?", "a": "Bratislava", "cat": "geografia", "dif": "facil", "lz": "B"},
  {"n": 382, "q": "¿Cuál es la capital oficial de Turquía?", "a": "Ankara", "cat": "geografia", "dif": "facil", "lz": "B"},
  {"n": 420, "q": "¿Cómo se denomina la región del espacio-tiempo alrededor de un agujero negro a partir de la cual nada puede escapar, ni siquiera la luz?", "a": "Horizonte de sucesos", "cat": "ciencia", "dif": "medio", "sabias": "El horizonte de sucesos no es una superficie sólida: es una frontera del espacio-tiempo. Una vez atravesada hacia el interior, ninguna señal puede regresar al exterior.", "lz": "A"},
  {"n": 128, "q": "¿Qué mamífero pone huevos?", "a": "El ornitorrinco", "cat": "ciencia", "dif": "facil", "sabias": "Junto con los equidnas forma los monotremas, los únicos mamíferos que ponen huevos.", "lz": "B"},
  {"n": 129, "q": "¿Qué científico descubrió la penicilina en 1928?", "a": "Alexander Fleming", "cat": "ciencia", "dif": "facil", "sabias": "Descubrió la penicilina por casualidad en 1928, al observar que un moho había matado las bacterias de una placa de cultivo.", "lz": "B"},
  {"n": 133, "q": "¿En qué capa de la atmósfera se concentra la mayor parte del ozono atmosférico?", "a": "Estratosfera", "cat": "ciencia", "dif": "facil", "lz": "B", "alias": ["La estratosfera"]},
  {"n": 384, "q": "¿Qué instrumento se utiliza para medir la cantidad de precipitación que cae en un lugar?", "a": "Pluviómetro", "cat": "ciencia", "dif": "facil", "lz": "B"},
  {"n": 399, "q": "¿Cuál es el mamífero terrestre más veloz del planeta, capaz de alcanzar puntas superiores a los 100 kilómetros por hora en carreras cortas?", "a": "Guepardo", "cat": "ciencia", "dif": "facil", "alias": ["Chita", "Cheetah"], "lz": "B"},
  {"n": 421, "q": "¿Cómo se llama la memoria de un ordenador que es volátil, es decir, que pierde su contenido cuando el equipo se apaga?", "a": "RAM", "cat": "cultura_general", "dif": "medio", "sabias": "RAM significa «Random Access Memory» porque permite acceder directamente a posiciones de memoria sin tener que recorrer secuencialmente las anteriores.", "alias": ["Memoria RAM"], "lz": "B"},
  {"n": 282, "q": "¿Cuál es la unidad básica de temperatura termodinámica en el Sistema Internacional?", "a": "Kelvin", "cat": "cultura_general", "dif": "facil", "sabias": "0 K equivale a −273,15 °C y es el cero absoluto, la temperatura más baja posible.", "lz": "B", "alias": ["El kelvin"]},
  {"n": 288, "q": "¿Cómo se llamaba el famoso rey de la mitología griega cuyo toque convertía instantáneamente cualquier objeto o alimento en oro macizo?", "a": "El rey Midas", "cat": "cultura_general", "dif": "facil", "lz": "B"},
  {"n": 422, "q": "¿Qué trilogía cinematográfica de Peter Jackson, estrenada entre 2001 y 2003, está basada en las novelas de J. R. R. Tolkien y obtuvo 17 premios Óscar en total?", "a": "El Señor de los Anillos", "cat": "arte_literatura", "dif": "medio", "sabias": "Las tres películas se rodaron casi a la vez, en un único rodaje principal de unos quince meses en Nueva Zelanda. La última entrega ganó los 11 Óscar a los que optaba, igualando el récord histórico.", "lz": "B"},
  {"n": 179, "q": "¿Quién creó al detective Sherlock Holmes?", "a": "Arthur Conan Doyle", "cat": "arte_literatura", "dif": "facil", "lz": "B"},
  {"n": 181, "q": "¿Qué instrumento musical de cuerda, muy similar a una guitarra pequeña de cuatro cuerdas, es tradicional de Hawái?", "a": "El ukelele", "cat": "arte_literatura", "dif": "facil", "lz": "B"},
  {"n": 186, "q": "¿Quién escribió La metamorfosis?", "a": "Franz Kafka", "cat": "arte_literatura", "dif": "facil", "lz": "B"},
  {"n": 211, "q": "¿Cómo se denomina una película que cuenta acontecimientos anteriores a los de otra película ya existente?", "a": "Precuela", "cat": "arte_literatura", "dif": "facil", "lz": "B"},
  {"n": 213, "q": "¿Quién dirigió la película El padrino, estrenada en 1972?", "a": "Francis Ford Coppola", "cat": "arte_literatura", "dif": "facil", "lz": "B"},
];;

